import React, { useState } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, 
  Users, HardHat, FileText, Settings, Power, 
  ChevronRight, Search, Filter, AlertCircle 
} from 'lucide-react';

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState('BINS');

  // THE 8-TAB MISSION CONTROL CONFIGURATION
  const navTabs = [
    { id: 'BINS', icon: <Trash2 size={20}/>, label: 'BIN_MONITOR' },
    { id: 'ZONES', icon: <Map size={20}/>, label: 'AREAS_ZONES' },
    { id: 'SCHEDULE', icon: <Calendar size={20}/>, label: 'COLL_SCHED' },
    { id: 'POINTS', icon: <Star size={20}/>, label: 'REWARDS_PEN' },
    { id: 'ANALYTICS', icon: <LineChart size={20}/>, label: 'ANALYTICS' },
    { id: 'CITIZENS', icon: <Users size={20}/>, label: 'CITIZEN_INF' },
    { id: 'WORKERS', icon: <HardHat size={20}/>, label: 'WORKER_DATA' },
    { id: 'REPORTS', icon: <FileText size={20}/>, label: 'SYS_REPORTS' },
  ];

  return (
    <div className="w-full max-w-[1440px] flex flex-col items-center justify-center p-4 animate-slot">

      {/* --- MAIN HARDWARE CHASSIS --- */}
      <div className="w-full bg-[#AB1717] border-[8px] border-[#47510B] rounded-[50px] p-6 red-stack-shadow flex flex-col gap-6 relative">

        {/* TOP HUD: SYSTEM BRANDING & TERMINAL STATUS */}
        <div className="flex justify-between items-center bg-[#47510B] p-4 rounded-2xl border-4 border-[#CAD23C]/20">
          <div className="flex items-center gap-6">
            <h1 className="text-3xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
              TRASH<span className="text-[#CAD23C]">2</span>TRACK <span className="text-xs opacity-40 ml-2">v3.0_ADMIN</span>
            </h1>
            <div className="h-8 w-[2px] bg-[#FDFAD8]/20" />
            <div className="flex flex-col">
              <span className="text-[10px] font-black text-[#CAD23C] uppercase">Active_Module</span>
              <span className="text-[#FDFAD8] font-mono text-sm uppercase">{activeTab}</span>
            </div>
          </div>
          <button className="bg-[#AB1717] p-2 px-6 rounded-xl border-2 border-[#FDFAD8]/40 text-[#FDFAD8] font-black text-xs hover:bg-[#FDFAD8] hover:text-[#AB1717] transition-all">
            SHUTDOWN_NODE
          </button>
        </div>

        <div className="flex flex-col lg:flex-row gap-6 h-[750px]">

          {/* --- LEFT CONTROL BANK (TABS 1-4) --- */}
          <div className="lg:w-1/6 flex flex-col gap-3">
            <p className="text-[10px] font-black text-[#FDFAD8] mb-1 opacity-60 ml-2 uppercase tracking-widest">Core_Ops</p>
            {navTabs.slice(0, 4).map((tab) => (
              <NavButton key={tab.id} tab={tab} activeTab={activeTab} setActiveTab={setActiveTab} />
            ))}
            <div className="mt-auto bg-[#47510B] p-4 rounded-2xl border-2 border-[#CAD23C]/20 flex flex-col items-center">
              <div className="w-full h-2 bg-[#CAD23C] rounded-full mb-2 animate-pulse" />
              <span className="text-[8px] font-black text-[#FDFAD8] uppercase">Signal_Stable</span>
            </div>
          </div>

          {/* --- CENTRAL MONITOR (THE CRT SCREEN) --- */}
          <div className="lg:w-4/6 bg-[#A1AED1] border-[6px] border-[#47510B] rounded-[40px] panel-inset-shadow overflow-hidden flex flex-col relative">
            {/* CRT Grid Pattern */}
            <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'linear-gradient(#47510B 1px, transparent 1px), linear-gradient(90deg, #47510B 1px, transparent 1px)', backgroundSize: '20px 20px' }} />

            <div className="relative z-10 p-8 h-full flex flex-col overflow-y-auto no-scrollbar text-[#47510B]">

              {/* RENDER CONTENT BASED ON TAB */}
              {activeTab === 'BINS' && <BinMonitoring />}
              {activeTab === 'REPORTS' && <ReportsPanel />}

              {/* Placeholder for others */}
              {!['BINS', 'REPORTS'].includes(activeTab) && (
                <div className="flex flex-col items-center justify-center h-full opacity-30 italic">
                  <Settings size={80} className="animate-spin-slow mb-4" />
                  <p className="font-black text-2xl uppercase tracking-[0.3em]">Loading_{activeTab}_Module</p>
                </div>
              )}
            </div>
          </div>

          {/* --- RIGHT CONTROL BANK (TABS 5-8) --- */}
          <div className="lg:w-1/6 flex flex-col gap-3 text-right">
            <p className="text-[10px] font-black text-[#FDFAD8] mb-1 opacity-60 mr-2 uppercase tracking-widest">Management</p>
            {navTabs.slice(4, 8).map((tab) => (
              <NavButton key={tab.id} tab={tab} activeTab={activeTab} setActiveTab={setActiveTab} align="right" />
            ))}
          </div>

        </div>
      </div>
    </div>
  );
};

// --- SUB-COMPONENT: MECHANICAL NAV BUTTON ---
const NavButton = ({ tab, activeTab, setActiveTab, align = "left" }) => (
  <button
    onClick={() => setActiveTab(tab.id)}
    className={`
      group flex items-center gap-3 p-4 rounded-2xl border-4 border-[#47510B] transition-all relative overflow-hidden
      ${activeTab === tab.id 
        ? 'bg-[#CAD23C] translate-x-0 shadow-none' 
        : `bg-[#FDFAD8] hover:bg-[#CAD23C]/50 ${align === 'left' ? '-translate-x-2' : 'translate-x-2'} shadow-[4px_4px_0_0_#47510B]`}
    `}
  >
    {align === "left" && <span className={activeTab === tab.id ? 'text-[#47510B]' : 'text-[#AB1717]'}>{tab.icon}</span>}
    <span className="text-[10px] font-black uppercase tracking-tighter flex-grow">{tab.label}</span>
    {align === "right" && <span className={activeTab === tab.id ? 'text-[#47510B]' : 'text-[#AB1717]'}>{tab.icon}</span>}

    {/* Active indicator light */}
    <div className={`absolute top-1 ${align === 'left' ? 'right-1' : 'left-1'} w-1.5 h-1.5 rounded-full ${activeTab === tab.id ? 'bg-[#AB1717] animate-pulse' : 'bg-[#47510B]'}`} />
  </button>
);

// --- TAB CONTENT: BIN MONITORING ---
const BinMonitoring = () => (
  <div className="animate-slot flex flex-col gap-6">
    <div className="flex justify-between items-end border-b-4 border-[#47510B]/20 pb-4">
      <h2 className="text-3xl font-black italic uppercase tracking-tighter">Bin_Health_Metrics</h2>
      <Search className="opacity-40" />
    </div>
    <div className="grid grid-cols-3 gap-4">
      {[ {l: 'HEALTH', v: '98%', c: 'text-green-600'}, {l: 'STATUS', v: 'ACTIVE', c: 'text-blue-600'}, {l: 'AVG_LOAD', v: '64%', c: 'text-[#AB1717]'} ].map((s, i) => (
        <div key={i} className="bg-[#FDFAD8] border-4 border-[#47510B] p-4 rounded-2xl shadow-[4px_4px_0_0_#47510B]">
          <p className="text-[9px] font-black uppercase opacity-60 mb-1">{s.l}</p>
          <p className={`text-2xl font-black ${s.c}`}>{s.v}</p>
        </div>
      ))}
    </div>
    <table className="w-full text-left border-collapse">
      <thead>
        <tr className="border-b-2 border-[#47510B]/20 font-black text-[11px] uppercase opacity-60">
          <th className="p-3">CODE</th><th className="p-3">ZONE</th><th className="p-3">CAPACITY</th><th className="p-3">STATUS</th>
        </tr>
      </thead>
      <tbody className="font-bold text-sm">
        {[1,2,3,4].map(i => (
          <tr key={i} className="border-b border-[#47510B]/10 hover:bg-[#FDFAD8]/30 transition-colors cursor-pointer">
            <td className="p-3 font-mono">B-NODE-0{i}</td>
            <td className="p-3">NORTH_SECTOR</td>
            <td className="p-3"><div className="w-full h-2 bg-[#FDFAD8] rounded-full border border-[#47510B]"><div className="h-full bg-[#AB1717] w-3/4" /></div></td>
            <td className="p-3"><span className="text-[9px] bg-green-200 px-2 py-1 rounded-md border border-green-600">OPTIMAL</span></td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

// --- TAB CONTENT: REPORTS PANEL ---
const ReportsPanel = () => (
  <div className="animate-slot flex flex-col gap-6">
    <div className="flex justify-between items-center bg-[#47510B] text-[#FDFAD8] p-4 rounded-2xl">
      <h3 className="font-black uppercase tracking-widest text-sm flex items-center gap-2"><Filter size={16}/> Filter_Issue_Logs</h3>
      <div className="flex gap-4 text-[10px] font-black">
        <span className="text-[#CAD23C] border-b-2 border-[#CAD23C] cursor-pointer">WORKER</span>
        <span className="opacity-40 cursor-pointer">SENSORS</span>
        <span className="opacity-40 cursor-pointer">CITIZEN</span>
      </div>
    </div>
    <div className="space-y-4">
      {[1, 2].map(i => (
        <div key={i} className="bg-[#FDFAD8] border-4 border-[#47510B] p-5 rounded-2xl shadow-[6px_6px_0_0_#47510B] flex gap-4">
          <AlertCircle className="text-[#AB1717] shrink-0" size={32} />
          <div>
            <p className="font-black uppercase text-xs mb-1">Worker_Report_ID: #8821</p>
            <p className="text-sm italic opacity-70">"Hydraulic lift malfunction on Unit_04. Immediate maintenance required in West_Area."</p>
            <button className="mt-3 text-[10px] font-black uppercase text-[#AB1717] flex items-center gap-1">RESOLVE_TICKET <ChevronRight size={12}/></button>
          </div>
        </div>
      ))}
    </div>
  </div>
);

export default Dashboard;
